CREATE TABLE public.whispers_staff_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, role text NOT NULL CHECK (role IN ('reviewer','expert')), workspace text NOT NULL CHECK (workspace IN ('ua','td','general')), invited_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', revoked_at timestamptz, accepted_at timestamptz, accepted_by uuid);
GRANT SELECT ON public.whispers_staff_invitations TO authenticated;
GRANT ALL ON public.whispers_staff_invitations TO service_role;
ALTER TABLE public.whispers_staff_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY scoped_admin_invitations ON public.whispers_staff_invitations FOR SELECT TO authenticated USING (public.whispers_access(workspace,'admin'));
CREATE FUNCTION public.whispers_accept_staff_invitations() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE verified_email text; invite public.whispers_staff_invitations; accepted integer:=0; BEGIN SELECT lower(email) INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF verified_email IS NULL THEN RAISE EXCEPTION 'Verified sign-in required'; END IF; FOR invite IN SELECT * FROM public.whispers_staff_invitations WHERE email=verified_email AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at>now() ORDER BY id FOR UPDATE LOOP IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=invite.invited_by AND role='admin' AND active AND invite.workspace=ANY(contexts)) THEN INSERT INTO public.user_roles(user_id,role,contexts,active) VALUES(auth.uid(),invite.role,ARRAY[invite.workspace],true) ON CONFLICT(user_id,role) DO UPDATE SET contexts=ARRAY(SELECT DISTINCT unnest(user_roles.contexts || excluded.contexts)),active=true; UPDATE public.whispers_staff_invitations SET accepted_at=now(),accepted_by=auth.uid() WHERE id=invite.id; INSERT INTO public.whispers_audit(actor_id,action,workspace,target_id) VALUES(auth.uid(),'accept_staff_invitation',invite.workspace,invite.id); accepted:=accepted+1; END IF; END LOOP; RETURN accepted; END $$;
REVOKE ALL ON FUNCTION public.whispers_accept_staff_invitations() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.whispers_accept_staff_invitations() TO authenticated;